class Solution {
public:
    long long sellingWood(int m, int n, std::vector<std::vector<int>>& prices) {
        std::vector<std::vector<long long>> dp(m + 1, std::vector<long long>(n + 1, 0));
        for (const auto& p : prices) {
            dp[p[0]][p[1]] = p[2];
        }
        for (int h = 1; h <= m; ++h) {
            for (int w = 1; w <= n; ++w) {
                for (int i = 1; i <= h / 2; ++i) {
                    dp[h][w] = std::max(dp[h][w], dp[i][w] + dp[h - i][w]);
                }
                for (int j = 1; j <= w / 2; ++j) {
                    dp[h][w] = std::max(dp[h][w], dp[h][j] + dp[h][w - j]);
                }
            }
        }
        return dp[m][n];
    }
};

class Solution {
    public long sellingWood(int m, int n, int[][] prices) {
        long[][] dp = new long[m + 1][n + 1];
        for (int[] p : prices) {
            dp[p[0]][p[1]] = p[2];
        }
        for (int h = 1; h <= m; h++) {
            for (int w = 1; w <= n; w++) {
                for (int i = 1; i <= h / 2; i++) {
                    dp[h][w] = Math.max(dp[h][w], dp[i][w] + dp[h - i][w]);
                }
                for (int j = 1; j <= w / 2; j++) {
                    dp[h][w] = Math.max(dp[h][w], dp[h][j] + dp[h][w - j]);
                }
            }
        }
        return dp[m][n];
    }
}

var sellingWood = function(m, n, prices) {
    const dp = Array.from({ length: m + 1 }, () => new Float64Array(n + 1));
    for (const [h, w, p] of prices) {
        dp[h][w] = p;
    }
    for (let h = 1; h <= m; h++) {
        for (let w = 1; w <= n; w++) {
            const halfH = h >> 1;
            for (let i = 1; i <= halfH; i++) {
                if (dp[i][w] + dp[h - i][w] > dp[h][w]) {
                    dp[h][w] = dp[i][w] + dp[h - i][w];
                }
            }
            const halfW = w >> 1;
            for (let j = 1; j <= halfW; j++) {
                if (dp[h][j] + dp[h][w - j] > dp[h][w]) {
                    dp[h][w] = dp[h][j] + dp[h][w - j];
                }
            }
        }
    }
    return dp[m][n];
};
